// DeepDipHold — a deep-dip swing bot for cbBTC (CBBTC/USDC).
//
// Idea: on this tape the one-minute noise is wide (about 6 bps per minute)
// and a full-size round trip costs roughly 30 bps in fees, slippage and
// price impact, so small edges are not edges at all. Only a genuinely deep
// fall is worth buying: the close down at least 100 bps over the last 60
// minutes. That is rare — three episodes in the 1,440-bar dev window — and
// each one is a real dislocation, not noise. The bot buys it in one full-size
// order and then simply holds: it sells only when the position has recovered
// 150 bps above its fill price, or when it has fallen a further 100 bps
// below it, and otherwise rides the position to the end of the window.
//
// Why not ladder or scale in: a second tranche a bar later buys a price that
// has already moved, and each bar's pool starts fresh, so splitting does not
// buy a better average here — it buys a later price. One order, one fill,
// one decision per episode.
//
// Why not exit on the mean: on this tape the price mean-reverts slowly and
// noisily; selling at the rolling mean exits for a few bps of profit and
// pays the round-trip cost again on the next episode. The take-profit is
// the exit: 150 bps is far enough above the ~30 bps round-trip cost to be
// a real win, and the stop is the only other way out.
//
// Risk: at most one position, at most $1,000 notional (the whole starting
// equity), long only, no leverage, no martingale — a failed dip costs one
// stop. After an exit the bot rests 60 bars before it may enter again, so
// one bad episode cannot chain into the next.
//
// Everything is a pure function of the bars and fills the harness sends: no
// wall clock, no network, no randomness, no files. Two runs on the same data
// reply byte for byte the same.

import { runBars, type Bar, type BarsState, type BuyInput, type SellInput } from './vendor/makefun-bars.ts';

const SYMBOL = 'CBBTC';
const BPS = 10_000n;

// --- signal: how deep the 60-minute fall must be
const LOOKBACK = 60; // bars
const DROP_BPS = -100; // 60-minute return, in bps

// --- exits, measured from the fill price
const TAKE_PROFIT_BPS = 150;
const STOP_BPS = -100;
const COOLDOWN_BARS = 60;

// --- execution
const MAX_SLIPPAGE_BPS = 100; // 1% past the latest close; fills move ~10 bps

type Phase =
  | 'flat' // no position, may enter
  | 'buySent' // buy ordered, awaiting its fill
  | 'held' // position open
  | 'sellSent'; // sell ordered, awaiting its fill

let closes: bigint[] = []; // closes, oldest first, capped at LOOKBACK + 1
let phase: Phase = 'flat';
let entryPrice: bigint = 0n; // fill price of the buy, at price_scale
let cooldown = 0;

function dropBps(now: bigint, then: bigint): bigint {
  // (now - then) / then in bps, truncated toward zero.
  return ((now - then) * BPS) / then;
}

function retBps(now: bigint, entry: bigint): bigint {
  return ((now - entry) * BPS) / entry;
}

await runBars({
  onBatch(state: BarsState, batch: { bars: Bar[]; fills: { client_id: string; side: 'buy' | 'sell'; status: 'filled' | 'rejected'; price: string }[] }): (BuyInput | SellInput)[] {
    // Fold this batch's fills into the phase machine first.
    for (const fill of batch.fills) {
      if (fill.side === 'buy' && phase === 'buySent') {
        if (fill.status === 'filled') {
          phase = 'held';
          entryPrice = BigInt(fill.price);
        } else {
          phase = 'flat';
        }
      } else if (fill.side === 'sell' && phase === 'sellSent') {
        if (fill.status === 'filled') {
          phase = 'flat';
          entryPrice = 0n;
          cooldown = COOLDOWN_BARS;
        } else {
          phase = 'held';
        }
      }
    }
    if (cooldown > 0) cooldown -= 1;

    const bar = batch.bars.find((b) => b.symbol === SYMBOL);
    if (bar === undefined) return [];
    closes.push(BigInt(bar.c));
    if (closes.length > LOOKBACK + 1) closes.shift();

    if (state.warmingUp) return [];
    const close = BigInt(bar.c);

    if (phase === 'flat' && cooldown === 0 && closes.length === LOOKBACK + 1) {
      const then = closes[0]!;
      if (dropBps(close, then) <= BigInt(DROP_BPS) && state.cash >= BigInt(state.hello.fees.min_notional_quote_units)) {
        phase = 'buySent';
        return [{ side: 'buy', symbol: SYMBOL, notional_quote_units: state.cash, max_slippage_bps: MAX_SLIPPAGE_BPS, client_id: `dip-${state.seq}` }];
      }
      return [];
    }

    if (phase === 'held' && entryPrice > 0n) {
      const pos = state.positions.get(SYMBOL);
      if (pos === undefined || pos.qty === 0n) {
        // The position is gone (flattened by the harness): back to flat.
        phase = 'flat';
        entryPrice = 0n;
        return [];
      }
      const ret = retBps(close, entryPrice);
      if (ret >= BigInt(TAKE_PROFIT_BPS) || ret <= BigInt(STOP_BPS)) {
        phase = 'sellSent';
        return [{ side: 'sell', symbol: SYMBOL, qty: pos.qty, max_slippage_bps: MAX_SLIPPAGE_BPS, client_id: `exit-${state.seq}` }];
      }
    }

    return [];
  },
});

// Wide-Trail Dip Recovery bot for the make.fun BTC race (agent-fun/bars-replay/v1).
//
// Thesis: on 1-minute cbBTC/USDC bars the market is choppy — most hours move
// less than 100 bps and pullbacks of 60-100 bps inside a recovery are routine
// noise. A tight trailing stop gets shaken out by that noise (on the dev
// window the classic 50 bps trail sold a winning dip at a loss, while the
// recovery then ran a further ~130 bps). So this bot buys only a deep,
// stabilised dip and then gives the recovery room: a 100 bps trailing stop
// that arms only once the position is 50 bps in profit, a 250 bps
// catastrophe stop, and up to 6 hours to let the recovery play out.
//
// Entry (all on closes, filled at the next bar's open):
//   - a deep drop: 60-minute return <= -140 bps, or 30-minute return <= -110 bps,
//   - AND the selling has abated: 5-minute return >= -40 bps and
//     15-minute return >= -10 bps (never buys a fresh low / a falling knife),
//   - 50% of cash in one tranche, no scale-in.
// Exit (whole position):
//   - trailing stop: 100 bps back from the highest close since entry, armed
//     once that peak is 50 bps above the entry price,
//   - catastrophe stop: -250 bps below entry,
//   - time stop: 360 minutes held,
//   - 10-minute cooldown after any exit before a new entry.
// A minute the recorder missed has no bar: the bot never decides on a stale
// close, it only folds the fills that arrived with that batch.
//
// How this differs from a plain dip-buy bot: the exit is the strategy, not
// the entry. A plain dip-buy arms a tight trail almost immediately and sells
// the first 50 bps pullback; this bot's 100 bps trail / 50 bps arm lets the
// position survive the normal 60-100 bps chop inside a recovery, and its
// 360-minute hold (vs the usual 240) lets a slow grind finish. It also
// commits half its cash in a single tranche instead of scaling in on further
// weakness, so it never averages down into a drop that keeps falling.
//
// Deterministic: no clock, no environment, no randomness — a pure function
// of the bars the harness sends. Standard library only, via the kit's
// vendored shim. One asset, long only, at most one open position.

import { runBars } from './vendor/makefun-bars.ts';

const SYMBOL = 'CBBTC';

// --- tuned parameters (bps unless noted) ---
const DROP_60_BPS = 140; // hourly drop that marks a deep-dip episode
const DROP_30_BPS = 110; // half-hour drop that marks one too
const FREEFALL_5_BPS = 40; // 5m return must be above -40 bps (not plunging)
const STAB_15_BPS = 10; // 15m return must be above -10 bps (selling abated)
const SIZE_PCT = 50; // entry buy: % of cash, single tranche, no scale-in
const TRAIL_BPS = 100; // trailing stop: bps back from the peak close
const TRAIL_ARM_BPS = 50; // trail arms once the peak is this far above entry
const STOP_BPS = 250; // catastrophe stop below entry
const HOLD_MAX_MIN = 360; // close any position older than this
const COOLDOWN_MIN = 10; // wait this long after an exit before re-entering
const HISTORY_MIN_BARS = 70; // bars of history needed before trading
const MAX_SLIPPAGE_BPS = 200; // fill guard vs the latest close
const MIN_NOTIONAL = 1_000_000n; // 1 USDC, in quote units

interface Mark {
  t: number;
  c: number;
}

const closes: Mark[] = [];

// Position state, maintained from the fills the harness reports.
let heldQty = 0; // asset units held (qty scale 8; doubles are exact here)
let entryPrice = 0; // fill price of the open position (raw price units)
let entryT = 0; // close time of the bar the entry filled on
let peak = 0; // highest close seen while holding
let cooldownUntil = 0; // ms; no new entry before this
let orderNo = 0;

function closeAt(t: number): number | null {
  // Latest close at or before t (t is a bar close time in ms).
  for (let i = closes.length - 1; i >= 0; i--) {
    if (closes[i].t <= t) return closes[i].c;
  }
  return null;
}

function retBps(now: number, t: number, minutes: number): number | null {
  const then = closeAt(t - minutes * 60_000);
  if (then === null || then <= 0) return null;
  return ((now / then) - 1) * 10_000;
}

await runBars({
  onBatch(state, batch) {
    // 1. Fold in the fills of the orders decided on the previous batch.
    for (const f of batch.fills) {
      if (f.symbol !== SYMBOL) continue;
      const price = Number(f.price);
      const qty = Number(f.qty) / 1e8;
      if (f.status === 'filled') {
        if (f.side === 'buy') {
          if (heldQty <= 0) {
            entryPrice = price;
            entryT = batch.t;
            peak = price;
          }
          heldQty += qty;
        } else {
          heldQty -= qty;
          if (heldQty <= 1e-12) {
            heldQty = 0;
            entryPrice = 0;
            peak = 0;
            cooldownUntil = batch.t + COOLDOWN_MIN * 60_000;
          }
        }
      }
    }

    // 2. Record this bar's close. A minute the recorder missed has no bar:
    // never decide on a stale close, only fold the fills that arrived.
    const bar = batch.bars.find((b) => b.symbol === SYMBOL);
    if (bar === undefined) return [];
    closes.push({ t: bar.t, c: Number(bar.c) });
    const now = closes[closes.length - 1].c;
    if (!(now > 0) || state.warmingUp) return [];
    if (closes.length <= HISTORY_MIN_BARS) return [];

    const t = batch.t;
    if (heldQty > 0 && !(entryPrice > 0)) return []; // corrupt state: stand still
    if (heldQty > 0) peak = Math.max(peak, now);
    const pos = state.positions.get(SYMBOL);
    const posQty = pos === undefined ? 0n : BigInt(pos.qty);

    // 3. Holding: exits first. The trail is wide on purpose: pullbacks of
    // 60-100 bps inside a recovery are noise, and a 50 bps trail sells them.
    if (heldQty > 0 && posQty > 0n) {
      const pnlBps = ((now / entryPrice) - 1) * 10_000;
      const trailBps = peak > entryPrice ? ((peak / now) - 1) * 10_000 : 0;
      const heldMin = (t - entryT) / 60_000;
      const armed = peak >= entryPrice * (1 + TRAIL_ARM_BPS / 10_000);
      const hitStop = pnlBps <= -STOP_BPS;
      const hitTrail = armed && trailBps >= TRAIL_BPS;
      const timedOut = heldMin >= HOLD_MAX_MIN;
      if (hitStop || hitTrail || timedOut) {
        orderNo += 1;
        return [{
          side: 'sell', symbol: SYMBOL, qty: posQty,
          max_slippage_bps: MAX_SLIPPAGE_BPS, client_id: `s${orderNo}`,
        }];
      }
      return [];
    }

    // 4. Flat: enter only on a deep drop that has stabilised.
    if (heldQty > 0) return []; // waiting on a fill to clear; do not double up
    if (t < cooldownUntil) return [];
    const r60 = retBps(now, t, 60);
    const r30 = retBps(now, t, 30);
    const r15 = retBps(now, t, 15);
    const r5 = retBps(now, t, 5);
    const deepDrop =
      (r60 !== null && r60 <= -DROP_60_BPS) ||
      (r30 !== null && r30 <= -DROP_30_BPS);
    const stabilised =
      (r5 === null || r5 >= -FREEFALL_5_BPS) &&
      (r15 === null || r15 >= -STAB_15_BPS);
    if (!deepDrop || !stabilised) return [];
    const notional = (state.cash * BigInt(SIZE_PCT)) / 100n;
    if (notional < MIN_NOTIONAL) return [];
    orderNo += 1;
    return [{
      side: 'buy', symbol: SYMBOL, notional_quote_units: notional,
      max_slippage_bps: MAX_SLIPPAGE_BPS, client_id: `b${orderNo}`,
    }];
  },
});

